//! Braid-group relations and the exact closure of a braid image.
//!
//! [`braid_relation_defects`] checks the defining relations of the braid group `B_n`
//! on a list of matrices `sigma_1, ..., sigma_{n-1}`: `sigma_i sigma_{i+1} sigma_i =
//! sigma_{i+1} sigma_i sigma_{i+1}`, `sigma_i sigma_j = sigma_j sigma_i` for `|i - j| >= 2`,
//! and invertibility. [`group_closure`] enumerates the group generated by matrices, exactly
//! and with a bound: either the complete finite group (its order and elements) or the
//! statement that the closure exceeds the bound. Modulo scalars (`projective = true`)
//! matrices are compared by their projective normal form (first nonzero entry `1`).
//!
//! What is and is not stated: a `Finite` outcome is a proof-by-enumeration that the
//! generated group has exactly that many elements; `ExceedsBound` is **not** a
//! certificate of infinity or of density (a finite group larger than the bound gives the
//! same outcome). Density of a braid image in a unitary group (the Fibonacci case) is a
//! theorem of the literature that this module does not establish.
//!
//! AuthorityEffect: None.
use std::collections::HashSet;
use std::hash::Hash;

use linear_algebra::backend::basic_matrix::{BasicMatrix, OperationLimits};

use crate::error::FusionError;
use crate::scalar::FusionScalar;
use linear_algebra::exact_field::{elimination, matrix};

/// Default allocation and aggregate scalar-work limits for a braid computation.
/// A larger explicit policy can be supplied to the `*_with_limits` entry points.
pub const DEFAULT_BRAID_LIMITS: OperationLimits = OperationLimits {
    max_elements: 1 << 20,
    max_scalar_ops: 1 << 26,
};

fn charge(what: &'static str, requested: u128, limit: usize) -> Result<(), FusionError> {
    if requested > limit as u128 {
        return Err(FusionError::Budget {
            what,
            requested,
            limit: limit as u128,
        });
    }
    Ok(())
}

fn product(factors: &[u128]) -> Result<u128, FusionError> {
    factors.iter().try_fold(1u128, |p, &factor| {
        p.checked_mul(factor).ok_or(FusionError::Overflow {
            context: "braid computation resource estimate",
        })
    })
}

/// A failed defining relation of the braid group (0-based generator numbers).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BraidRelationDefect {
    /// `sigma_i sigma_{i+1} sigma_i != sigma_{i+1} sigma_i sigma_{i+1}`.
    Braid { i: usize },
    /// `sigma_i sigma_j != sigma_j sigma_i` with `|i - j| >= 2`.
    Far { i: usize, j: usize },
    /// `sigma_i` is not invertible.
    Singular { i: usize },
}

/// Every violated defining relation of the braid group among the generators.
pub fn braid_relation_defects<K: FusionScalar>(
    generators: &[BasicMatrix<K>],
) -> Result<Vec<BraidRelationDefect>, FusionError> {
    braid_relation_defects_with_limits(generators, DEFAULT_BRAID_LIMITS)
}

/// [`braid_relation_defects`] with an aggregate operation budget.
pub fn braid_relation_defects_with_limits<K: FusionScalar>(
    generators: &[BasicMatrix<K>],
    limits: OperationLimits,
) -> Result<Vec<BraidRelationDefect>, FusionError> {
    let n = generators.first().map_or(0, BasicMatrix::rows);
    check_generator_shapes(
        generators,
        n,
        "braid relations (one square generator shape)",
    )?;
    relation_admission(generators.len(), n, limits)?;
    let mut defects = Vec::new();
    singular_defects(generators, n, limits, &mut defects)?;
    for i in 0..generators.len() {
        pair_defects(generators, i, limits, &mut defects)?;
    }
    Ok(defects)
}

fn check_generator_shapes<K: FusionScalar>(
    generators: &[BasicMatrix<K>],
    n: usize,
    operation: &'static str,
) -> Result<(), FusionError> {
    if let Some(bad) = generators.iter().find(|m| m.shape() != (n, n)) {
        return Err(FusionError::Shape {
            operation,
            left: (n, n),
            right: bad.shape(),
        });
    }
    Ok(())
}

fn relation_admission(
    generators: usize,
    n: usize,
    limits: OperationLimits,
) -> Result<(), FusionError> {
    let g = generators as u128;
    let dimension = n as u128;
    charge(
        "braid generator storage",
        product(&[g, dimension, dimension])?,
        limits.max_elements,
    )?;
    // At most four products for each adjacent pair, two for each other pair,
    // and one row reduction per generator. This bounds the complete replay.
    let products = product(&[g, g.saturating_sub(1)])?
        .checked_add(4 * g.saturating_sub(1))
        .ok_or(FusionError::Overflow {
            context: "braid relation count",
        })?;
    let work = product(&[2, products, dimension, dimension, dimension])?
        .checked_add(product(&[3, g, dimension, dimension, dimension])?)
        .and_then(|work| work.checked_add(g * dimension * (dimension + 1)))
        .ok_or(FusionError::Overflow {
            context: "braid relation scalar work",
        })?;
    charge("braid relation scalar work", work, limits.max_scalar_ops)?;
    Ok(())
}

fn singular_defects<K: FusionScalar>(
    generators: &[BasicMatrix<K>],
    n: usize,
    limits: OperationLimits,
    defects: &mut Vec<BraidRelationDefect>,
) -> Result<(), FusionError> {
    for (i, generator) in generators.iter().enumerate() {
        if n == 0 || elimination::rank_with_limits(generator, limits)? < n {
            defects.push(BraidRelationDefect::Singular { i });
        }
    }
    Ok(())
}

fn pair_defects<K: FusionScalar>(
    generators: &[BasicMatrix<K>],
    i: usize,
    limits: OperationLimits,
    defects: &mut Vec<BraidRelationDefect>,
) -> Result<(), FusionError> {
    // The caller enumerates the slice, so i is in range.
    let a = &generators[i];
    if let Some(b) = generators.get(i + 1) {
        let left = braid_triple(a, b, limits)?;
        let right = braid_triple(b, a, limits)?;
        if left != right {
            defects.push(BraidRelationDefect::Braid { i });
        }
    }
    for (j, b) in generators.iter().enumerate().skip(i + 2) {
        if matrix::multiply_with_limits(a, b, limits)?
            != matrix::multiply_with_limits(b, a, limits)?
        {
            defects.push(BraidRelationDefect::Far { i, j });
        }
    }
    Ok(())
}

fn braid_triple<K: FusionScalar>(
    a: &BasicMatrix<K>,
    b: &BasicMatrix<K>,
    limits: OperationLimits,
) -> Result<BasicMatrix<K>, FusionError> {
    matrix::multiply_with_limits(&matrix::multiply_with_limits(a, b, limits)?, a, limits)
        .map_err(FusionError::from)
}

/// The projective normal form of a matrix: `(m / lambda, lambda)` where `lambda` is the
/// first nonzero entry in row-major order; `None` for the zero matrix.
pub fn projective_normal_form<K: FusionScalar>(
    m: &BasicMatrix<K>,
) -> Result<Option<(BasicMatrix<K>, K)>, FusionError> {
    let Some(first) = m.as_slice().iter().find(|entry| !entry.is_zero()) else {
        return Ok(None);
    };
    let lambda = first.clone();
    let scale = core_number_theory::scalar::inverse(&lambda).map_err(FusionError::from)?;
    Ok(Some((
        matrix::scale(m, &scale).map_err(FusionError::from)?,
        lambda,
    )))
}

/// `Some(lambda)` with `b = lambda a` and `lambda != 0` when the two matrices are
/// proportional; `None` otherwise (including when exactly one is zero).
pub fn equal_up_to_scalar<K: FusionScalar>(
    a: &BasicMatrix<K>,
    b: &BasicMatrix<K>,
) -> Result<Option<K>, FusionError> {
    if a.shape() != b.shape() {
        return Ok(None);
    }
    match (projective_normal_form(a)?, projective_normal_form(b)?) {
        (Some((na, la)), Some((nb, lb))) => {
            if na == nb {
                Ok(Some(
                    core_number_theory::scalar::divide(&lb, &la).map_err(FusionError::from)?,
                ))
            } else {
                Ok(None)
            }
        }
        _ => Ok(None),
    }
}

/// A finite matrix group enumerated exactly.
#[derive(Debug, Clone)]
pub struct FiniteMatrixGroup<K> {
    elements: Vec<BasicMatrix<K>>,
    index: HashSet<Vec<K>>,
    projective: bool,
    dimension: usize,
}

impl<K: FusionScalar + Hash + Eq> FiniteMatrixGroup<K> {
    /// The number of elements (of the projective group when `projective`).
    pub fn order(&self) -> usize {
        self.elements.len()
    }

    /// The elements (in projective normal form when `projective`).
    pub fn elements(&self) -> &[BasicMatrix<K>] {
        &self.elements
    }

    /// Whether the group was enumerated modulo scalars.
    pub fn is_projective(&self) -> bool {
        self.projective
    }

    /// Whether a matrix is in the group (up to a scalar when projective).
    pub fn contains(&self, m: &BasicMatrix<K>) -> Result<bool, FusionError> {
        if m.shape() != (self.dimension, self.dimension) {
            return Ok(false);
        }
        if !self.projective {
            return Ok(self.index.contains(m.as_slice()));
        }
        let key = {
            match projective_normal_form(m)? {
                Some((normal, _)) => normal,
                None => return Ok(false),
            }
        };
        Ok(self.index.contains(key.as_slice()))
    }
}

/// The outcome of a bounded closure.
#[derive(Debug, Clone)]
pub enum ClosureOutcome<K> {
    /// The generated group has exactly this many elements.
    Finite(FiniteMatrixGroup<K>),
    /// More than `bound` elements were found. Not a certificate of infiniteness.
    ExceedsBound { bound: usize },
}

impl<K> ClosureOutcome<K> {
    /// The order when the outcome is `Finite`.
    pub fn order(&self) -> Option<usize> {
        match self {
            Self::Finite(group) => Some(group.elements.len()),
            Self::ExceedsBound { .. } => None,
        }
    }
}

/// Enumerates the group generated by square matrices of one size, by breadth-first
/// multiplication, stopping when more than `bound` elements are found.
pub fn group_closure<K: FusionScalar + Hash + Eq>(
    generators: &[BasicMatrix<K>],
    bound: usize,
    projective: bool,
) -> Result<ClosureOutcome<K>, FusionError> {
    group_closure_with_limits(generators, bound, projective, DEFAULT_BRAID_LIMITS)
}

/// [`group_closure`] with limits on aggregate live storage and scalar work.
/// All generators must be nonempty, square, and invertible before enumeration.
pub fn group_closure_with_limits<K: FusionScalar + Hash + Eq>(
    generators: &[BasicMatrix<K>],
    bound: usize,
    projective: bool,
    limits: OperationLimits,
) -> Result<ClosureOutcome<K>, FusionError> {
    let n = closure_dimension(generators)?;
    let mut work = closure_admission(generators, n, limits)?;
    if bound == 0 {
        return Ok(ClosureOutcome::ExceedsBound { bound });
    }
    let mut group = initial_group(n, projective, limits)?;
    let mut next = 0;
    // Appended elements are the BFS frontier: no second matrix queue or clone.
    while next < group.elements.len() {
        if !expand_closure(&mut group, next, generators, bound, limits, &mut work)? {
            return Ok(ClosureOutcome::ExceedsBound { bound });
        }
        next += 1;
    }
    Ok(ClosureOutcome::Finite(group))
}

fn closure_dimension<K: FusionScalar>(generators: &[BasicMatrix<K>]) -> Result<usize, FusionError> {
    let Some(first) = generators.first() else {
        return Err(FusionError::ListLength {
            what: "generators",
            expected: 1,
            got: 0,
        });
    };
    let n = first.rows();
    if n == 0 || first.cols() != n {
        return Err(FusionError::NotSquare {
            operation: "group closure (generators must share one square shape)",
            rows: first.rows(),
            cols: first.cols(),
        });
    }
    check_generator_shapes(generators, n, "group closure (one square generator shape)")?;
    Ok(n)
}

fn closure_admission<K: FusionScalar>(
    generators: &[BasicMatrix<K>],
    n: usize,
    limits: OperationLimits,
) -> Result<u128, FusionError> {
    let d = n as u128;
    let entries = d * d;
    charge(
        "group generator storage",
        product(&[generators.len() as u128, entries])?,
        limits.max_elements,
    )?;
    let work = product(&[generators.len() as u128, d, 2 * entries + d + 1])?;
    charge("group admission scalar work", work, limits.max_scalar_ops)?;
    for generator in generators {
        if elimination::rank_with_limits(generator, limits)? != n {
            return Err(FusionError::Singular {
                context: "group closure generator",
            });
        }
    }
    Ok(work)
}

fn normalized<K: FusionScalar>(
    mut m: BasicMatrix<K>,
    projective: bool,
) -> Result<BasicMatrix<K>, FusionError> {
    if !projective {
        return Ok(m);
    }
    let first =
        m.as_slice()
            .iter()
            .find(|entry| !entry.is_zero())
            .ok_or(FusionError::Inconsistent {
                context: "a product of invertible group generators is zero",
            })?;
    let scale = core_number_theory::scalar::inverse(first).map_err(FusionError::from)?;
    // Keep the already owned dense product. No second matrix allocation/clone.
    let cols = m.cols();
    for i in 0..m.as_slice().len() {
        let value = scale.mul(&m.as_slice()[i]);
        m.set(i / cols, i % cols, value)?;
    }
    Ok(m)
}

fn initial_group<K: FusionScalar + Hash + Eq>(
    n: usize,
    projective: bool,
    limits: OperationLimits,
) -> Result<FiniteMatrixGroup<K>, FusionError> {
    // Two retained scalar arrays per state (ordered element and hash key),
    // plus two dense scratch arrays for a product and projective normalization.
    charge(
        "group closure storage",
        4 * (n as u128) * (n as u128),
        limits.max_elements,
    )?;
    // The identity is already projectively canonical; no inverse or scaled copy.
    let identity = matrix::identity_with_limits::<K>(n, limits)?;
    let key = identity.as_slice().to_vec();
    Ok(FiniteMatrixGroup {
        elements: vec![identity],
        index: HashSet::from([key]),
        projective,
        dimension: n,
    })
}

fn record_element<K: FusionScalar + Hash + Eq>(
    group: &mut FiniteMatrixGroup<K>,
    h: BasicMatrix<K>,
    bound: usize,
) -> bool {
    if group.index.contains(h.as_slice()) {
        return true;
    }
    if group.elements.len() >= bound {
        return false;
    }
    group.index.insert(h.as_slice().to_vec());
    group.elements.push(h);
    true
}

fn expand_closure<K: FusionScalar + Hash + Eq>(
    group: &mut FiniteMatrixGroup<K>,
    current: usize,
    generators: &[BasicMatrix<K>],
    bound: usize,
    limits: OperationLimits,
    work: &mut u128,
) -> Result<bool, FusionError> {
    let d = group.dimension as u128;
    let entries = d * d;
    for s in generators {
        charge(
            "group closure storage",
            2 * (group.elements.len() as u128 + 1) * entries,
            limits.max_elements,
        )?;
        *work = work
            .checked_add(2 * d * entries + if group.projective { entries + 1 } else { 0 })
            .ok_or(FusionError::Overflow {
                context: "group closure scalar work",
            })?;
        charge("group closure scalar work", *work, limits.max_scalar_ops)?;
        let h = normalized(
            matrix::multiply_with_limits(&group.elements[current], s, limits)?,
            group.projective,
        )?;
        if !record_element(group, h, bound) {
            return Ok(false);
        }
    }
    Ok(true)
}

